using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["environment"] = "production",
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30,
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        }
    };

    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"), Description("Returns the current application configuration")]
    public static string GetAppSettings() =>
        JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });

    [McpServerResource(UriTemplate = "config://app/version", Name = "App Version",
        MimeType = "text/plain"), Description("Returns the application version string")]
    public static string GetVersion() => "1.0.0-preview";
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Checks if a specific feature flag is enabled")]
    public static string CheckFeatureFlag(
        [Description("Name of the feature flag to check")] string flagName)
    {
        var flags = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        };

        return flags.TryGetValue(flagName, out var enabled)
            ? $"Feature '{flagName}' is {(enabled ? "enabled" : "disabled")}"
            : $"Feature '{flagName}' not found";
    }

    [McpServerTool, Description("Lists all available configuration keys")]
    public static string ListConfigKeys() =>
        string.Join(", ", new[] { "environment", "maxRetries", "timeoutSeconds", "features" });
}

